+// https://github.com/microsoft/TypeScript/issues/60573
+
+type Wrapper<T> = {
+    _type: T;
+};
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" };
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj };
+}
+
+export const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">,
+    prop2: <Wrapper<"world">>stringWrapper(),
+});
+
+type Unwrap<T extends Wrapper<any>> = T["_type"] extends Record<string, Wrapper<any>> ? { [Key in keyof T["_type"]]: Unwrap<T["_type"][Key]>; }
+    : T["_type"];
+
+type Test = Unwrap<typeof value>;
+
+// should be { prop1: "hello"; prop2: "world"; }
+export const test: Test = null!;
+export const error1: number = test;
+
