+export const test = null;
+export const error1 = test;
+// the same, but with the types of the properties not being preserved by an alias
+export const unwrapped = unwrap(value);
+// Type parameters in the assertion must be instantiated
+function generic(x) {
+    return { prop: [], other: [] };
+}
+export const instantiated = generic("a");
+class C {
+    prop1 = w;
+    prop2 = w;
+    prop3 = 1;
+    prop4 = [];
+}
+export const mappedClass = mapClass(new C());
+
