+//// [typeAssertionInPropertyOfMappedType.d.ts]
+type Wrapper<T> = {
+    _type: T;
+};
+export declare const value: Wrapper<{
+    prop1: Wrapper<"hello">;
+    prop2: Wrapper<"world">;
+}>;
+type Unwrap<T extends Wrapper<any>> = T["_type"] extends Record<string, Wrapper<any>> ? {
+    [Key in keyof T["_type"]]: Unwrap<T["_type"][Key]>;
+} : T["_type"];
+type Test = Unwrap<typeof value>;
+export declare const test: Test;
+export declare const error1: number;
+export declare const unwrapped: {
+    prop1: "hello";
+    prop2: "world";
+};
+export declare const instantiated: {
+    prop: string[];
+    other: string[];
+};
+export declare const mappedClass: {
+    prop1: [Wrapper<"hello">];
+    prop2: [Wrapper<"world">];
+    prop3: [number];
+    prop4: [string[]];
+};
+export {};
